INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-01','Multimeter Loading Effect on High-Impedance Circuit','Easy','ECE','arena','diagnose','Measurements & Instrumentation','multiple_choice','A DMM with input impedance 10 MΩ is used to measure voltage across a 10 MΩ resistor. The measured voltage will be:','{"choices": ["Correct, because DMM impedance is high", "Exactly half the true voltage — DMM in parallel forms a voltage divider 10 MΩ||10 MΩ = 5 MΩ", "Double the true voltage", "Zero volts"], "correct": 1}'::jsonb,'V_measured = V_true × Z_DMM/(Z_source + Z_DMM) = V_true × 10/(10+10) = V_true/2. Loading is critical when source impedance is comparable to meter impedance. Use a higher-impedance electrometer for mega-ohm sources.','{multiple_choice}'::text[],0.82) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-02','Oscilloscope Bandwidth and Rise Time','Easy','ECE','arena','calculate','Measurements & Instrumentation','multiple_choice','An oscilloscope has bandwidth BW = 200 MHz. The rise time it can measure accurately is:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-03','True RMS vs Average-Responding Multimeter','Easy','ECE','arena','select','Measurements & Instrumentation','multiple_choice','Why use a True-RMS multimeter instead of an average-responding multimeter for measuring non-sinusoidal waveforms?','{"choices": ["True-RMS meters are always more accurate", "Average-responding meters assume sinusoidal waveforms (correction factor 1.11). For square waves, PWM, or distorted waveforms, this gives wrong results. True-RMS correctly measures actual heating power regardless of waveform shape", "True-RMS meters have higher input impedance", "Average-responding meters cannot measure AC"], "correct": 1}'::jsonb,'Average-responding meter: V_display = 1.11 × V_avg (calibrated for sine). For a 5 V square wave: V_avg = 5 V (50% duty), so meter reads 5.55 V (wrong). True-RMS: √(average of V²) = 5 V (correct). Essential for VFD motor measurements.','{multiple_choice}'::text[],0.75) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-04','Thermocouple Working Principle','Easy','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A thermocouple measures temperature using:','{"choices": ["Resistance change with temperature", "The Seebeck effect — two dissimilar metals joined at two junctions produce a voltage proportional to the temperature difference between hot (measuring) and cold (reference) junctions", "Capacitance change with temperature", "Infrared emission from the hot junction"], "correct": 1}'::jsonb,'Seebeck effect: V = S × ΔT where S is the Seebeck coefficient (µV/°C, different for each thermocouple type). Types: K (Chromel-Alumel, −200 to +1350°C), J (Iron-Constantan), T (Copper-Constantan). Cold junction compensation required.','{multiple_choice}'::text[],0.85) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-05','Wheatstone Bridge: Sensitivity','Easy','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A Wheatstone bridge is used to measure small resistance changes in a strain gauge. Why is a bridge circuit preferred over direct resistance measurement?','{"choices": ["Bridges measure absolute resistance more accurately", "Bridge circuits can detect very small fractional resistance changes (ΔR/R) by measuring a small differential voltage — null-balance technique eliminates supply voltage errors and common-mode noise", "Bridges require less power", "Bridges are simpler to build"], "correct": 1}'::jsonb,'At balance, output = 0 V. Small ΔR creates a measurable small differential voltage. The supply noise and thermal drift appear as common-mode and are rejected. A direct ohmmeter would have 1% accuracy; a bridge can resolve 0.001% changes.','{multiple_choice}'::text[],0.8) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-06','Signal Conditioning: Instrumentation Amplifier','Medium','ECE','arena','select','Measurements & Instrumentation','multiple_choice','A thermocouple produces 41 µV/°C (Type K) and is connected 2 m from the measurement circuit. The cable picks up 50 Hz noise. Best signal conditioning approach:','{"choices": ["Use a high-gain single-ended amplifier at the end of the cable", "Use a twisted-pair cable with shielding, followed by an instrumentation amplifier with high CMRR — the differential signal (thermocouple) is amplified while 50 Hz common-mode noise is rejected", "Use a 10 kΩ pull-up resistor on the signal line", "Add a 100 µF bypass capacitor at the measurement end"], "correct": 1}'::jsonb,'Thermocouple output is differential and microvolts-level. 50 Hz mains appears as common-mode on both wires. Twisted pair + shield minimises loop area (reduces inductive pickup). INA amplifies differential signal while rejecting common-mode (CMRR > 80 dB).','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-07','Spectrum Analyser vs Oscilloscope','Medium','ECE','arena','compare','Measurements & Instrumentation','multiple_choice','A spectrum analyser is more appropriate than an oscilloscope for:','{"choices": ["Measuring signal timing relationships between two channels", "Identifying harmonic distortion, spurious emissions, modulation sidebands, and frequency components of a signal — it displays signal amplitude vs frequency (frequency domain)", "Measuring pulse width and rise time", "Checking logic signal levels"], "correct": 1}'::jsonb,'Oscilloscope: amplitude vs time (time domain). Spectrum analyser: amplitude vs frequency (frequency domain). To see that a 100 MHz oscillator also emits at 200 MHz (harmonic) or has a 1 MHz spur, you need a spectrum analyser. Essential for EMC testing.','{multiple_choice}'::text[],0.76) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-08','4-Wire (Kelvin) Resistance Measurement','Medium','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A 4-wire Kelvin resistance measurement is used instead of 2-wire when measuring:','{"choices": ["High resistance values (> 1 MΩ)", "Very low resistances (< 1 Ω) — Kelvin connection eliminates lead/contact resistance from the measurement: separate current and voltage leads", "AC resistances", "Inductances below 1 µH"], "correct": 1}'::jsonb,'2-wire: measured resistance includes lead resistance (0.1–1 Ω typical). For a 0.01 Ω shunt, lead resistance >> measurement. 4-wire: current flows through outer leads; voltage is sensed by inner leads at the component terminals (no current → no voltage drop in sense leads).','{multiple_choice}'::text[],0.78) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-09','LCR Meter: Test Frequency Selection','Medium','ECE','arena','select','Measurements & Instrumentation','multiple_choice','When measuring the ESR (Equivalent Series Resistance) of a 100 µF aluminium electrolytic capacitor intended for use at 100 kHz, the LCR meter test frequency should be set to:','{"choices": ["1 kHz (standard factory setting)", "DC", "100 kHz — ESR is frequency-dependent; measuring at the actual operating frequency gives the relevant ESR value", "1 MHz"], "correct": 2}'::jsonb,'ESR of electrolytic capacitors is highly frequency-dependent. A cap showing 0.5 Ω at 1 kHz may have 0.05 Ω at 100 kHz. Always measure at the circuit''s operating frequency. LCR meters with swept frequency (Bode plot mode) are ideal.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-10','LVDT (Linear Variable Differential Transformer)','Medium','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','An LVDT position sensor offers advantages over potentiometric (wiper-type) sensors for precision linear displacement measurement because:','{"choices": ["LVDT has simpler electronics", "LVDT has no moving contacts — inductive coupling with movable core provides theoretically infinite resolution, no wear, and operates in harsh environments (sealed, oil-filled)", "LVDT has higher output voltage", "LVDT measures angular position only"], "correct": 1}'::jsonb,'LVDT: AC-excited primary coil, two secondary coils. Moving ferromagnetic core shifts coupling. No friction, no wear, sub-micron resolution, operable in extreme environments. Used in precision machine tools, aircraft, and structural testing.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-11','Calibration vs Verification','Medium','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','The difference between instrument calibration and verification is:','{"choices": ["They are the same process", "Verification confirms an instrument is within specification (pass/fail); Calibration is the process of adjusting an instrument to minimise measurement error, using traceable reference standards", "Calibration is performed by the user; verification by the manufacturer", "Verification requires a reference standard; calibration does not"], "correct": 1}'::jsonb,'Verification: compare instrument readings to reference → determine if within specification tolerance. Calibration: measure, then adjust (or characterise) the instrument to bring readings within specification, traceable to national/international standards (SI units). ISO 17025 governs calibration laboratories.','{multiple_choice}'::text[],0.7) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-12','Measurement Uncertainty: Type A vs Type B','Medium','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','In metrology, Type A uncertainty is evaluated by:','{"choices": ["Manufacturer''s specifications and calibration certificates", "Statistical analysis of a series of repeated measurements — calculating standard deviation of measured values", "Reference to published material data", "Engineering judgement only"], "correct": 1}'::jsonb,'Type A: statistical analysis — measure N times, calculate standard deviation, then standard uncertainty = s/√N. Type B: non-statistical — from calibration certificates, datasheets, previous measurements. GUM (Guide to Uncertainty in Measurement) defines both.','{multiple_choice}'::text[],0.65) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-13','Clamp Meter Operating Principle','Hard','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A clamp meter measures current without breaking the circuit. For DC current measurement, it uses:','{"choices": ["A transformer (current transformer principle)", "An inductive sense coil", "A Hall-effect sensor — magnetic field from DC current is detected by the Hall sensor inside the clamp jaw", "A thermocouple"], "correct": 2}'::jsonb,'Current transformers only work with AC (require changing flux). Hall-effect clamp meters work for DC: jaw acts as magnetic core concentrating B field from conductor current; Hall sensor produces V_H ∝ B ∝ I. Both AC and DC clamp meters use Hall effect; AC-only meters use CT.','{multiple_choice}'::text[],0.68) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-14','VNA: S-Parameters Meaning','Hard','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A VNA (Vector Network Analyser) measures S-parameters. S₂₁ represents:','{"choices": ["Input reflection coefficient (how much signal reflects back from port 1)", "Reverse transmission from port 2 to port 1", "Forward transmission gain from port 1 to port 2 — ratio of signal transmitted to port 2 relative to signal incident on port 1", "Reverse reflection coefficient at port 2"], "correct": 2}'::jsonb,'S-parameter Sᵢⱼ: signal at port i due to stimulus at port j (all other ports matched). S₁₁ = input reflection; S₂₁ = forward transmission; S₁₂ = reverse transmission; S₂₂ = output reflection. S₂₁ in dB = insertion gain/loss.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-15','Lock-In Amplifier Application','Hard','ECE','arena','select','Measurements & Instrumentation','multiple_choice','A lock-in amplifier is used to measure a 1 µV signal buried in noise with SNR of −40 dB (noise 100× larger). It works by:','{"choices": ["High-gain amplification followed by filtering", "Multiplying the input signal with a reference at the same frequency and phase, then low-pass filtering — only the component at exactly the reference frequency passes; all other noise is rejected", "Averaging many measurements", "Using a very narrow bandpass filter at the signal frequency"], "correct": 1}'::jsonb,'Lock-in amplification: input × reference → DC component + 2× frequency component. After LPF: only DC remains, proportional to signal amplitude and cos(phase difference). Effectively a very narrow bandpass filter (bandwidth = LPF bandwidth, not signal frequency). Essential in MEMS, photodetection, and chemical sensing.','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-16','RTD vs Thermocouple: Selection Criteria','Hard','ECE','arena','compare','Measurements & Instrumentation','multiple_choice','A Pt100 RTD is preferred over a Type K thermocouple for a pharmaceutical clean-room temperature monitoring application (−10°C to +50°C range) because:','{"choices": ["RTDs have higher maximum temperature range", "RTDs are self-powered (no external supply needed)", "RTDs have higher accuracy and stability in narrow temperature ranges — Pt100 offers ±0.1°C accuracy vs thermocouple ±0.5–1°C, no cold-junction compensation needed, and better long-term stability", "RTDs respond faster to temperature changes"], "correct": 2}'::jsonb,'RTD (Pt100): resistance changes with temperature (0.385 Ω/°C). Accuracy ±0.1°C, drift < 0.1°C/year. Thermocouple: requires CJC (cold junction compensation adds error), higher temperature range. For −10 to +50°C precision: RTD wins. For >300°C: thermocouple.','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-17','Dead Weight Tester: Pressure Calibration','Hard','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A dead weight tester generates a precise known pressure using:','{"choices": ["A precision electronic pressure regulator", "A calibrated gas cylinder", "Known masses applied to a piston of known area: P = F/A = mg/A — gravitational force on mass creates traceable, calculable pressure without relying on a secondary standard", "Bourdon tube expansion"], "correct": 2}'::jsonb,'P = mg/A where m = calibrated mass, g = local gravitational acceleration (must be measured at site), A = piston area. The National Measurement Institutes maintain primary pressure standards using dead weight testers (piston gauges) with uncertainties of 0.001%.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-18','Sampling Oscilloscope vs Real-Time Oscilloscope','Hard','ECE','arena','compare','Measurements & Instrumentation','multiple_choice','A sampling oscilloscope can display signals at 40 GHz despite using a slower ADC because:','{"choices": ["It uses a faster ADC than real-time scopes", "It reconstructs periodic waveforms by sampling at different phases across many repetitions (equivalent time sampling) — requiring the signal to be repetitive and stable", "It has wider bandwidth front-end electronics", "It uses digital interpolation algorithms"], "correct": 1}'::jsonb,'Equivalent time sampling (ETS): trigger on each cycle, delay sample point by δt each repetition. After N cycles: complete waveform reconstructed with time resolution δt. Only works for repetitive signals. Real-time scope: single-shot capture, bandwidth limited by ADC speed (few GHz currently).','{multiple_choice}'::text[],0.55) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-19','Total Measurement Uncertainty Calculation','Hard','ECE','arena','calculate','Measurements & Instrumentation','multiple_choice','Two uncorrelated measurement uncertainties: u₁ = 2 mV, u₂ = 3 mV. Combined standard uncertainty:
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-20','Grounding and Shielding in Instrumentation','Hard','ECE','arena','select','Measurements & Instrumentation','multiple_choice','In a sensitive instrumentation system, a shield (driven shield) driven by the amplifier output is used because:','{"choices": ["To provide a return current path for the signal", "Driven shield (guard) maintains the same potential as the centre conductor — eliminates capacitive current from shield to signal, drastically reducing cable capacitance effect and leakage errors in high-impedance measurements", "To protect against ESD", "To reduce cable inductance"], "correct": 1}'::jsonb,'Passive shield: reduces external noise coupling but adds cable capacitance (C_shield-signal). Driven shield (bootstrap/guard): V_shield = V_signal → no voltage difference → zero capacitive current → C_eff ≈ 0. Essential for sub-pA measurements (electrometers, pH meters).','{multiple_choice}'::text[],0.52) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-21','Precision vs Accuracy','Hard','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A set of 10 measurements clusters tightly together (0.1% spread) but all are 5% away from the true value. This instrument is:','{"choices": ["Both accurate and precise", "Accurate but not precise", "Neither accurate nor precise", "Precise but not accurate — reproducible readings with systematic offset (bias); bias can be corrected by calibration"], "correct": 3}'::jsonb,'Precision = repeatability (low random error). Accuracy = closeness to true value (low systematic error). Precise but inaccurate: systematic bias. After calibration removes the bias, the instrument becomes both precise and accurate. Accuracy requires both calibration and precision.','{multiple_choice}'::text[],0.72) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-22','Digital Storage Oscilloscope: Aliasing','Hard','ECE','arena','diagnose','Measurements & Instrumentation','multiple_choice','A DSO with 1 GSa/s sample rate displays a 480 MHz signal that appears as a 20 MHz sine wave. This is:','{"choices": ["Correct measurement — 20 MHz and 480 MHz are harmonically related", "Aliasing — 480 MHz sampled at 1 GSa/s: f_alias = |f_signal − f_sample| = |480 − 1000| = 520 MHz... but stroboscopic effect: 480 MHz with 1 GSa/s → f_alias = 1000 − 480 = 520 MHz, appearing as 520 MHz. If it shows 20 MHz, check sample rate setting", "A filtering artefact", "Normal oscilloscope operation at this frequency"], "correct": 1}'::jsonb,'At 1 GSa/s, Nyquist = 500 MHz. 480 MHz is below Nyquist — should display correctly. If showing 20 MHz, the actual sample rate may be lower than indicated. True aliasing: f_signal > Nyquist → f_alias = |f_sig − N×f_s| for nearest integer N.','{multiple_choice}'::text[],0.5) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-23','Power Analyser: Reactive Power Measurement','Hard','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A power analyser measures V = 230 V, I = 10 A, apparent power S = 2300 VA, and power factor PF = 0.8 lagging. What is the reactive power Q?','{"choices": ["1840 VAR", "1380 VAR", "2300 VAR", "920 VAR"], "correct": 1}'::jsonb,'P = S × PF = 2300 × 0.8 = 1840 W. Q = √(S² − P²) = √(2300² − 1840²) = √(5290000 − 3385600) = √1904400 ≈ 1380 VAR. Power triangle: S² = P² + Q².','{multiple_choice}'::text[],0.6) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-24','Noise Floor and Dynamic Range','Hard','ECE','arena','interpret','Measurements & Instrumentation','multiple_choice','A spectrum analyser has a noise floor of −130 dBm and can display up to +30 dBm before overload. The dynamic range is:','{"choices": ["130 dB", "160 dB", "30 dB", "100 dB"], "correct": 1}'::jsonb,'Dynamic range = maximum signal level − minimum detectable signal = +30 dBm − (−130 dBm) = 160 dB. Dynamic range determines the ability to simultaneously see strong and weak signals. High dynamic range is critical for spurious emission testing.','{multiple_choice}'::text[],0.62) ON CONFLICT (slug) DO NOTHING;
INSERT INTO problems (slug,title,difficulty,category,source,mechanic,track,interaction_type,statement,options,editorial,languages,acceptance_rate) VALUES ('ece-mi-25','Sensor Linearisation Techniques','Hard','ECE','arena','select','Measurements & Instrumentation','multiple_choice','A thermistor has a highly nonlinear resistance-temperature characteristic (NTC: R = A × exp(B/T)). To obtain a linear 0–5 V output proportional to temperature, the best approach is:','{"choices": ["Use it without linearisation for accuracy", "Add a parallel resistor to linearise the curve in a narrow range, then amplify — or use a microcontroller with lookup table/polynomial for full-range linearisation", "Use a higher supply voltage", "Connect the thermistor in series with an inductor"], "correct": 1}'::jsonb,'Hardware linearisation: a parallel resistor (at R = R₀) gives a quasi-linear region of ±15% over ~30°C. Software linearisation: ADC reads raw resistance, MCU applies Steinhart-Hart equation or lookup table to get accurate temperature. MCU approach is more accurate and flexible.','{multiple_choice}'::text[],0.58) ON CONFLICT (slug) DO NOTHING;
